export const GLOBAL_GENRE_SHARE: Readonly<Record<string, number>> = {"fantasy":0.098,"comedy":0.302,"adventure":0.093,"science fiction":0.086,"family":0.075,"action":0.175,"drama":0.407,"biography":0.045,"musical":0.038,"animation":0.027,"western":0.007,"romance":0.134,"documentary":0.045,"horror":0.093,"crime":0.101,"thriller":0.142,"sport":0.01,"mystery":0.044,"war":0.022,"legal":0.002,"medical":0.002};

/** How much more of a genre a country makes than the world does. One is average. */
export function genreLift(countryId: string, genreId: string): number {
  const share = MARKET_PROFILES[countryId]?.genres[genreId] ?? 0;
  const world = GLOBAL_GENRE_SHARE[genreId] ?? 0.01;
  return share / world;
}
